import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int md = sc.nextInt();

        long[] factorial = new long[n + 1];
        long[] invFactorial = new long[n + 1];

        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = (factorial[i - 1] * i) % md;
        }

        // Modular exponentiation
        long modPow(long base, int exp) {
            long res = 1;
            long b = base;
            int e = exp;
            while (e > 0) {
                if ((e & 1) == 1) res = (res * b) % md;
                b = (b * b) % md;
                e >>= 1;
            }
            return res;
        }

        invFactorial[n] = modPow(n, md - 2);
        for (int i = n; i >= 1; i--) {
            invFactorial[i - 1] = (invFactorial[i] * i) % md;
        }

        // Function for nCr
        long nCr(int a, int b) {
            if (b < 0 || b > a) return 0;
            return (((factorial[a] * invFactorial[b]) % md) * invFactorial[a - b]) % md;
        }

        long[] g = new long[n + 1];
        long[] f = new long[n + 1];

        for (int i = 0; i <= n; i++) {
            g[i] = 1;
            f[i] = 0;
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                long now = (nCr(i - 1, j - 1) * (i + 1)) % md;
                g[i] = (g[i] + (g[j - 1] * g[i - j] % md) * now) % md;
                f[i] = (f[i] + (f[j - 1] * g[i - j] % md) * now) % md;
                f[i] = (f[i] + (g[j - 1] * f[i - j] % md) * now) % md;
                long add_value = ((long)(j - 1) * j / 2 + (long)(i - j) * (i - j + 1) / 2);
                f[i] = (f[i] + nCr(i - 1, j - 1) * g[j - 1] % md * g[i - j] % md * add_value) % md;
            }
        }

        int[][][] dp = new int[n + 1][m + 1][2];
        int[][][] dp2 = new int[n + 1][m + 1][2];

        dp[0][0][1] = 0;
        dp2[0][0][1] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                int val1 = 0;
                int val2 = 0;
                if (j >= 0) {
                    int sum1 = (dp[i - 1][j][0] + dp[i - 1][j][1]) % md;
                    int sum2 = (dp2[i - 1][j][0] + dp2[i - 1][j][1]) % md;
                    dp[i][j][1] = sum1;
                    dp2[i][j][1] = sum2;
                }
                for (int k = 1; k <= j; k++) {
                    long c = nCr(j, k);
                    long val1Long = (long)dp2[i - k][j - k][1] * f[k] % md;
                    long val2Long = (long)dp[i - k][j - k][1] * g[k] % md;
                    int cInt = (int)c;
                    int val1Int = (int)val1Long;
                    int val2Int = (int)val2Long;

                    dp[i][j][0] = (int)((dp[i][j][0] + (long)cInt * val1Int) % md);
                    dp[i][j][0] = (int)((dp[i][j][0] + (long)cInt * val2Int) % md);
                    dp2[i][j][0] = (int)((dp2[i][j][0] + (long)cInt * val2Int) % md);
                }
            }
        }

        int result = (dp[n][m][0] + dp[n][m][1]) % md;
        System.out.println(result);
    }
}

